        xMSF->createInstance(u"com.sun.star.sheet.FunctionDescriptions"_ustr), UNO_QUERY_THROW);

    uno::Reference<container::XNameAccess> xNA(xFDs, UNO_QUERY_THROW);
    uno::Sequence<OUString> names = xNA->getElementNames();

